            if habit.name == habitName {
                habit.isCompleted = true
                habit.streak += 1
                updateStats()
                return
            }
        }
    }

    func resetHabit(habitName: String) {
        habits.forEach { habit in
            if habit.name == habitName {
                habit.isCompleted = false
                habit.streak = 0
                updateStats()
                return
            }
        }
    }

    func updateStats() {
        var total = 0
        var maxStreak = 0
        var streaks = [Int: Int]()
        var streakCount = 0

        habits.forEach { habit in
            if habit.isCompleted {
                total += 1
                if habit.streak > maxStreak {
                    maxStreak = habit.streak
                }
                streaks[habit.streak, default: 0] += 1
                streakCount += 1
            }
